    /// GlobalThisGetProperty/GlobalThisSetProperty. The syntactic `globalThis.X`
    /// path is still intercepted at compile time by GlobalThisStaticEmitter.
    /// </summary>
    public FieldBuilder GlobalThisSingletonField { get; set; } = null!;
